import express from "express";
import { describe, expect, it } from "vitest";
import request from "supertest";
import { createRateLimiter } from "../src/middleware/rateLimiter.js";

function createTestApp(now: () => number) {
  const app = express();
  app.use(createRateLimiter({ limit: 2, windowMs: 1_000, now }));
  app.get("/", (_req, res) => res.json({ status: "ok" }));
  return app;
}

describe("rate limiter", () => {
  it("enforces the configured token limit", async () => {
    let currentTime = 0;
    const app = createTestApp(() => currentTime);

    expect((await request(app).get("/")).status).toBe(200);
    expect((await request(app).get("/")).status).toBe(200);
    const limited = await request(app).get("/");

    expect(limited.status).toBe(429);
    expect(limited.body).toEqual({ error: "Too many requests" });
    expect(limited.headers["retry-after"]).toBe("1");
    expect(limited.headers["ratelimit-remaining"]).toBe("0");
    currentTime = 100;
    expect((await request(app).get("/")).status).toBe(429);
  });

  it("allows requests again as tokens refill", async () => {
    let currentTime = 0;
    const app = createTestApp(() => currentTime);

    await request(app).get("/");
    await request(app).get("/");
    expect((await request(app).get("/")).status).toBe(429);

    currentTime = 500;
    expect((await request(app).get("/")).status).toBe(200);
  });
});

